for record in records:
    if record.status == 'alert' and not record.alert_sent:
        # Send email alert
        template = env.ref('saas_portal_quotas.email_template_quota_alert', raise_if_not_found=False)
        if template and record.client_id.partner_id.email:
            template.send_mail(record.id, force_send=True)
            record.write({'alert_sent': True})

for record in records:
    if record.status == 'warning':
        # Send warning notification
        template = env.ref('saas_portal_quotas.email_template_quota_warning', raise_if_not_found=False)
        if template and record.client_id.partner_id.email:
            template.send_mail(record.id, force_send=True)

for record in records:
    if record.status == 'blocked':
        # Send block notification and block operations
        template = env.ref('saas_portal_quotas.email_template_quota_blocked', raise_if_not_found=False)
        if template and record.client_id.partner_id.email:
            template.send_mail(record.id, force_send=True)

        # Auto-upgrade if configured
        if record.client_id.plan_id.quota_auto_upgrade and record.client_id.plan_id.quota_upgrade_plan_id:
            # Trigger upgrade process (would need implementation)
            pass
